// Normalizar y validar TaskPayload<MitigationWriterInput>
const input = $input.first().json;

if (!input.taskId || !input.inputData || !input.inputData.clauseId) {
  throw new Error('Payload inválido: taskId y inputData.clauseId son requeridos.');
}

return [{
  json: {
    taskId: input.taskId,
    auditId: input.auditId,
    clauseId: input.inputData.clauseId,
    clauseType: input.inputData.clauseType,
    verbatimText: input.inputData.verbatimText,
    riskAssessment: JSON.stringify(input.inputData.riskAssessment, null, 2),
    advocacyPosition: input.inputData.advocacyPosition || 'BALANCED'
  }
}];

